-- Importe em um banco novo. As tabelas antigas não são alteradas.
CREATE DATABASE IF NOT EXISTS mathfund CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mathfund;
CREATE TABLE IF NOT EXISTS mf_players (
  id VARCHAR(64) PRIMARY KEY,
  email VARCHAR(190) NULL UNIQUE,
  state LONGTEXT NOT NULL,
  xp INT UNSIGNED NOT NULL DEFAULT 0,
  listed TINYINT(1) NOT NULL DEFAULT 0,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX ranking (listed, xp)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Banco de perguntas: importação repetida preserva edições existentes.
CREATE TABLE IF NOT EXISTS mf_questions (
  id VARCHAR(64) PRIMARY KEY,
  grade VARCHAR(8) NOT NULL,
  question_number SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  topic VARCHAR(190) NOT NULL,
  difficulty TINYINT UNSIGNED NOT NULL,
  payload LONGTEXT NOT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX grade_topic (grade, topic)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

